import React from "react";

import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  PieChart,
  Pie,
  Cell,
  BarChart,
  Bar,
  Legend,
} from "recharts";

import "./DashboardCharts.css";

// Illustrative data for UI development.
// Replace with backend API data during integration.

const revenueData = [
  { month: "May", revenue: 12000 },
  { month: "Jun", revenue: 18000 },
  { month: "Jul", revenue: 15000 },
  { month: "Aug", revenue: 25000 },
  { month: "Sep", revenue: 22000 },
  { month: "Oct", revenue: 32000 },
];

const subscriptionData = [
  { name: "Active", value: 65, color: "#2563eb" },
  { name: "Draft", value: 15, color: "#f59e0b" },
  { name: "Closed", value: 10, color: "#ef4444" },
  { name: "Quotation", value: 10, color: "#8b5cf6" },
];

const invoiceData = [
  { month: "May", paid: 30, pending: 15, overdue: 5 },
  { month: "Jun", paid: 40, pending: 12, overdue: 8 },
  { month: "Jul", paid: 35, pending: 18, overdue: 7 },
  { month: "Aug", paid: 50, pending: 15, overdue: 10 },
  { month: "Sep", paid: 45, pending: 20, overdue: 5 },
  { month: "Oct", paid: 60, pending: 12, overdue: 8 },
];

function RevenueChart() {
  return (
    <div className="chart-card revenue-chart">
      <div className="chart-heading">
        <div>
          <h3>Revenue Analytics</h3>
          <p>Monthly revenue overview</p>
        </div>
        <span className="chart-period">Last 6 Months</span>
      </div>

      <ResponsiveContainer width="100%" height={280}>
        <LineChart data={revenueData}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} />
          <XAxis dataKey="month" axisLine={false} tickLine={false} />
          <YAxis
            axisLine={false}
            tickLine={false}
            tickFormatter={(value) => `₹${value / 1000}k`}
          />
          <Tooltip
            formatter={(value) => [
              `₹${value.toLocaleString("en-IN")}`,
              "Revenue",
            ]}
          />
          <Line
            type="monotone"
            dataKey="revenue"
            stroke="#2563eb"
            strokeWidth={3}
            dot={{ r: 4 }}
            activeDot={{ r: 7 }}
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

function SubscriptionChart() {
  return (
    <div className="chart-card">
      <div className="chart-heading">
        <div>
          <h3>Subscription Overview</h3>
          <p>Distribution by status</p>
        </div>
      </div>

      <ResponsiveContainer width="100%" height={280}>
        <PieChart>
          <Pie
            data={subscriptionData}
            dataKey="value"
            nameKey="name"
            innerRadius={65}
            outerRadius={95}
            paddingAngle={4}
          >
            {subscriptionData.map((entry) => (
              <Cell key={entry.name} fill={entry.color} />
            ))}
          </Pie>
          <Tooltip formatter={(value) => `${value}%`} />
          <Legend verticalAlign="bottom" />
        </PieChart>
      </ResponsiveContainer>
    </div>
  );
}

function InvoiceChart() {
  return (
    <div className="chart-card invoice-chart">
      <div className="chart-heading">
        <div>
          <h3>Invoice Analytics</h3>
          <p>Monthly invoice status comparison</p>
        </div>
      </div>

      <ResponsiveContainer width="100%" height={280}>
        <BarChart data={invoiceData}>
          <CartesianGrid strokeDasharray="3 3" vertical={false} />
          <XAxis dataKey="month" axisLine={false} tickLine={false} />
          <YAxis axisLine={false} tickLine={false} />
          <Tooltip />
          <Legend />
          <Bar dataKey="paid" name="Paid" fill="#16a34a" radius={[4, 4, 0, 0]} />
          <Bar dataKey="pending" name="Pending" fill="#f59e0b" radius={[4, 4, 0, 0]} />
          <Bar dataKey="overdue" name="Overdue" fill="#ef4444" radius={[4, 4, 0, 0]} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

function DashboardCharts() {
  return (
    <div className="dashboard-charts">
      <RevenueChart />

      <div className="charts-row">
        <SubscriptionChart />
        <InvoiceChart />
      </div>
    </div>
  );
}

export default DashboardCharts;
